from flask import Flask, render_template, request, redirect, url_for, session, flash
import config
import mysql.connector as connector
from werkzeug.utils import secure_filename
import os
from ultralytics import YOLO
import bcrypt
from collections import Counter
from dotenv import load_dotenv
import json
import pandas as pd
from insurance_predictor import predict_insurance

load_dotenv()

app = Flask(__name__)
app.secret_key = os.getenv('SECRET_KEY')

# Load car part prices JSON
with open('car_parts_prices.json', 'r') as f:
    CAR_PART_PRICES = json.load(f)

# Load internal damage prices JSON 
# with open("internal_damage_map.json") as f:
#     INTERNAL_DAMAGE = json.load(f)


def connect_to_db():
    try:
        connection = connector.connect(**config.mysql_credentials)
        return connection
    except connector.Error as e:
        print(f"Error connecting to database: {e}")
        return None


@app.route('/')
def home():
    return render_template('index.html')


@app.route('/signup', methods=['GET', 'POST'])
def signup():
    if request.method == 'POST':
        name = request.form.get('name')

        password = request.form.get('password')
        email = request.form.get('email')
        vehicle_id = request.form.get('vehicleId')
        contact_number = request.form.get('phoneNumber')
        address = request.form.get('address')
        car_brand = request.form.get('carBrand')
        model = request.form.get('carModel')

        # print("DATA from form")
        # print(f"name : {name}")
        # print(f"email : {email}")
        # print(f"password : {password}")
        # print(f"vehicle_id : {vehicle_id}")
        # print(f"contact_number : {contact_number}")
        # print(f"address : {address}")
        # print(f"car_brand : {car_brand}")
        # print(f"model : {model}")

        if not all([name, password, email, vehicle_id, contact_number, address, car_brand, model]):
            flash("All fields are required!", "error")
            return render_template('signup.html')

        hashed_password = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')

        connection = connect_to_db()
        if connection:
            try:
                with connection.cursor() as cursor:
                    query = '''
                    INSERT INTO user_info (name, password, email, vehicle_id, contact_number, address, car_brand, model)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                    '''
                    cursor.execute(query, (name, hashed_password, email, vehicle_id, contact_number, address, car_brand, model))
                    connection.commit()
                    session['user_email'] = email
                    flash("Signup successful!", "success")
                    return redirect(url_for('dashboard'))
            except connector.IntegrityError as e:
                if 'Duplicate entry' in str(e):
                    flash("Email already exists. Please use a different email.", "error")
                else:
                    flash("An error occurred while signing up. Please try again.", "error")
            except connector.Error as e:
                print(f"Error executing query: {e}")
                flash("An error occurred while signing up. Please try again.", "error")
        else:
            flash("Database connection failed. Please try again later.", "error")

    return render_template('signup.html')


@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')
        print(f"Email : {email}")
        print(f"Password : {password}")

        if not email or not password:
            flash("Email and password are required!", "error")
            return render_template('login.html')

        connection = connect_to_db()
        if connection:
            try:
                with connection.cursor() as cursor:
                    query = "SELECT password FROM user_info WHERE email = %s"
                    cursor.execute(query, (email,))
                    result = cursor.fetchone()

                    if result is None:
                        flash("Email not registered.", "error")

                    elif bcrypt.checkpw(
                            password.encode('utf-8'),
                            result[0].encode('utf-8')
                        ):
                        session['user_email'] = email
                        flash("Login successful!", "success")
                        return redirect(url_for('dashboard'))

                    else:
                        flash("Incorrect password.", "error")

            except connector.Error as e:
                print(f"Error executing query: {e}")
                flash("An error occurred during login. Please try again.", "error")
        else:
            flash("Database connection failed. Please try again later.", "error")

    return render_template('login.html')


@app.route('/logout')
def logout():
    session.pop('user_email', None)
    flash("You have been logged out.", "info")

    return redirect(url_for('login'))


# Load YOLO model
import os

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
model_path = os.path.join(BASE_DIR, "models", "model weights", "best.pt")

model = YOLO(model_path)


@app.route('/dashboard', methods=['GET', 'POST'])
def dashboard():

    if 'user_email' not in session:
        flash("Please login first.", "error")
        return redirect(url_for('login'))

    if request.method == 'POST':
        file = request.files.get('image')
        if not file:
            flash('Please upload an image.', 'error')
            return render_template('dashboard.html')

        filename = secure_filename(file.filename)
        if not filename.lower().endswith(('.png', '.jpg', '.jpeg')):
            flash('Invalid file type. Please upload an image.', 'error')
            return render_template('dashboard.html')

        # Save uploaded image
        image_path = os.path.join(BASE_DIR, "static", "uploaded_image.jpg")

        file.save(image_path)

        # YOLO Prediction
        result = model(image_path)
        detected_objects = result[0].boxes
        class_ids = [box.cls.item() for box in detected_objects]
        class_counts = Counter(class_ids)

        # Save detected image
        detected_image_path = os.path.join(BASE_DIR, "static", "detected_image.jpg")
        import cv2

        annotated = result[0].plot()
        cv2.imwrite(detected_image_path, annotated)

        # Session check
        user_email = session.get('user_email')
        if not user_email:
            flash('You need to log in to get an estimate.', 'error')
            return redirect(url_for('login'))

        # Get part prices
        part_prices = get_part_prices(user_email, class_counts)
        # Convert detected parts to match JSON keys
        part_prices_fixed = {}

        for part, price in part_prices.items():
            part_prices_fixed[part.capitalize()] = price


        # ================= REPAIR TOTAL =================
        repair_total = sum([p['total'] for p in part_prices.values()])

        severity, risk, drivable, safety = calculate_damage_severity(part_prices, repair_total)

        repair_days, completion, resale, depreciation = predictive_analytics(
            part_prices, repair_total, severity
        )

        internal_cost, internal_breakdown = calculate_internal_damage(part_prices_fixed)




        # ================= INSURANCE INPUT =================
        insurance_input = {
            "policy_tenure": 1,
            "age_of_car": 2,
            "age_of_policyholder": 30,
            "population_density": 5000,
            "airbags": 2,
            "displacement": 1200,
            "cylinder": 4,
            "gear_box": 5,
            "ncap_rating": 4
        }

        # ================= INSURANCE PREDICTION =================
        insurance_prediction = 0
        insurance_cost = 0

        try:
            insurance_prediction = predict_insurance(insurance_input)
            print("Insurance Prediction:", insurance_prediction)

            if insurance_prediction == 1 or repair_total > 20000:
                insurance_prediction = 1
                insurance_cost = repair_total * 0.7

        except Exception as e:
            print("Insurance Prediction Error:", e)

        # ================= FINAL COST =================
        final_total = repair_total - insurance_cost
        # ================= RECOMMENDATION =================
        recommendations = generate_recommendation(
            repair_days,
            depreciation,
            final_total
        )
        insurance_cost = round(insurance_cost, 2)
        internal_cost = round(internal_cost, 2)
        repair_total = round(repair_total, 2)
        final_total = round(final_total, 2)

        print("Repair:", repair_total)
        print("Insurance Cover:", insurance_cost)
        print("Final:", final_total)

        # ================= SEND TO HTML =================
        return render_template(
            'estimate.html',
            original_image='uploaded_image.jpg',
            detected_image='detected_image.jpg',
            part_prices=part_prices,
            repair_total=repair_total,
            insurance_prediction=insurance_prediction,
            insurance_cost=insurance_cost,
            final_total=final_total,
            severity=severity,
            risk=risk,
            drivable=drivable,
            safety=safety,
            repair_days=repair_days,
            completion=completion,
            resale=resale,
            depreciation=depreciation,
            internal_cost=internal_cost,
            internal_breakdown=internal_breakdown,
            recommendations=recommendations
        )


    return render_template('dashboard.html')



def get_part_prices(email, class_counts):
    """
    Get repair prices for detected parts using the JSON price file.
    """
    connection = connect_to_db()
    if connection:
        try:
            with connection.cursor(dictionary=True) as cursor:
                # Get user's car brand and model
                cursor.execute("SELECT car_brand, model FROM user_info WHERE email = %s", (email,))
                user_data = cursor.fetchone()
                if not user_data:
                    print("User not found")
                    return {}

                car_brand = user_data['car_brand'].strip().upper()
                car_model = user_data['model'].strip().title()

                print(f"Fetching prices for {car_brand} {car_model}")

                prices = {}
                for class_id, count in class_counts.items():
                    part_name = get_part_name_from_id(class_id)
                    if part_name:
                        # Fetch price from JSON
                        try:
                            price_per_part = CAR_PART_PRICES[car_brand][car_model][part_name]
                            total_price = price_per_part * count
                            prices[part_name] = {'count': count, 'price': price_per_part, 'total': total_price}
                        except KeyError:
                            print(f"Price not found for {car_brand} {car_model} part {part_name}")
                            prices[part_name] = {'count': count, 'price': 0, 'total': 0}
                return prices
        except connector.Error as e:
            print(f"Error executing query: {e}")
            return {}
    print("Connection failed")
    return {}

#Severity Function
def calculate_damage_severity(part_prices, repair_total):

    damaged_parts = list(part_prices.keys())
    parts_count = len(damaged_parts)

    high_parts = ["Bonnet", "Windshield"]
    medium_parts = ["Door", "Fender"]
    low_parts = ["Light", "Bumper", "Dickey"]

    high_hit = any(p in damaged_parts for p in high_parts)
    medium_hit = any(p in damaged_parts for p in medium_parts)

    # ================= SEVERITY =================
    if repair_total > 50000 or high_hit:
        severity = "Major"
    elif repair_total > 20000 or medium_hit:
        severity = "Moderate"
    else:
        severity = "Minor"

    # ================= RISK =================
    if severity == "Major":
        risk = "High"
    elif severity == "Moderate":
        risk = "Medium"
    else:
        risk = "Low"

    # ================= DRIVABLE =================
    if severity == "Major":
        drivable = "Not Drivable"
    elif severity == "Moderate":
        drivable = "Limited Driving"
    else:
        drivable = "Drivable"

    # ================= SAFETY =================
    if high_hit:
        safety = "Dangerous"
    elif medium_hit:
        safety = "Warning"
    else:
        safety = "Safe"

    return severity, risk, drivable, safety

#Predictive Analysis function
def predictive_analytics(part_prices, repair_total, severity):

    parts_count = len(part_prices.keys())

    # ================= REPAIR TIME =================
    if severity == "Major":
        repair_days = 7 + parts_count
    elif severity == "Moderate":
        repair_days = 3 + parts_count
    else:
        repair_days = 1 + parts_count

    # ================= COMPLETION STATUS =================
    if repair_days <= 3:
        completion = "Fast Track"
    elif repair_days <= 7:
        completion = "On Track"
    else:
        completion = "Delayed"

    # ================= RESALE IMPACT =================
    if severity == "Major":
        resale = "High Impact"
    elif severity == "Moderate":
        resale = "Medium Impact"
    else:
        resale = "Stable"

    # ================= DEPRECIATION =================
    if repair_total > 60000:
        depreciation = "High"
    elif repair_total > 25000:
        depreciation = "Medium"
    else:
        depreciation = "Low"

    return repair_days, completion, resale, depreciation

#internal damage cost function
def calculate_internal_damage(part_prices):

    # Load JSON mapping
    with open("internal_damage_map.json", "r") as f:
        internal_damage_map = json.load(f)

    total_internal_cost = 0
    internal_breakdown = []

    # Loop through detected damaged parts
    for part in part_prices.keys():

        # ✅ Skip if part not in JSON
        if part not in internal_damage_map:
            continue

        # Get internal items
        internal_items = internal_damage_map[part]

        # Loop internal damage possibilities
        for item in internal_items:

            internal_part = item.get("part", "Unknown")
            probability = item.get("probability", 0)
            cost = item.get("cost", 0)

            # Probability weighted cost
            estimated_cost = probability * cost

            total_internal_cost += estimated_cost

            internal_breakdown.append({
                "external_part": part,
                "internal_part": internal_part,
                "probability": probability,
                "estimated_cost": round(estimated_cost)
            })

    return round(total_internal_cost), internal_breakdown




def get_part_name_from_id(class_id):
    class_names = ['Bonnet', 'Bumper', 'Dickey', 'Door', 'Fender', 'Light', 'Windshield']
    if 0 <= class_id < len(class_names):
        return class_names[int(class_id)]
    return None


@app.route('/view_profile')
def view_profile():
    if 'user_email' not in session:
        flash('You need to login to view your profile.', 'error')
        return redirect(url_for('login'))

    connection = connect_to_db()
    if connection:
        try:
            with connection.cursor(dictionary=True) as cursor:
                # Fetch current user information
                cursor.execute("SELECT * FROM user_info WHERE email = %s", (session['user_email'],))
                user_info = cursor.fetchone()
                if not user_info:
                    flash('User not found.', 'error')
                    return redirect(url_for('dashboard'))
                return render_template('view_profile.html', user_info=user_info)
        except connector.Error as e:
            print(f"Error executing query: {e}")
            flash("An error occurred while fetching your profile. Please try again.", "error")
    else:
        flash("Database connection failed. Please try again later.", "error")

    return redirect(url_for('dashboard'))


@app.route('/edit_profile', methods=['GET', 'POST'])
def edit_profile():
    if 'user_email' not in session:
        flash('You need to login to edit your profile.', 'error')
        return redirect(url_for('login'))

    connection = connect_to_db()
    if connection:
        try:
            with connection.cursor(dictionary=True) as cursor:
                if request.method == 'POST':
                    # Update user information
                    query = '''
                    UPDATE user_info
                    SET name = %s, email = %s, vehicle_id = %s, contact_number = %s, 
                        address = %s, car_brand = %s, model = %s
                    WHERE email = %s
                    '''
                    cursor.execute(query, (
                        request.form['name'],
                        request.form['email'],
                        request.form['vehicleId'],
                        request.form['phoneNumber'],
                        request.form['address'],
                        request.form['carBrand'],
                        request.form['carModel'],
                        session['user_email']
                    ))
                    connection.commit()
                    flash('Profile updated successfully!', 'success')
                    session['user_email'] = request.form['email']  # Update session if email changed
                    return redirect(url_for('dashboard'))

                # Fetch current user information
                cursor.execute("SELECT * FROM user_info WHERE email = %s", (session['user_email'],))
                user_info = cursor.fetchone()
                return render_template('edit_profile.html', user_info=user_info)

        except connector.Error as e:
            print(f"Error executing query: {e}")
            flash("An error occurred while updating your profile. Please try again.", "error")
    else:
        flash("Database connection failed. Please try again later.", "error")

    return redirect(url_for('dashboard'))

#Recommendation
def generate_recommendation(repair_days, depreciation, final_amount):
    recommendations = []

    # Repair time logic
    if repair_days > 7:
        recommendations.append("Vehicle may require extended workshop time. Plan alternate transport.")
    else:
        recommendations.append("Repair duration is within normal range.")

    # Depreciation logic
    if "High" in depreciation or "-" in depreciation:
        recommendations.append("Significant resale value impact expected.")
    else:
        recommendations.append("Minimal impact on resale value.")

    # Cost logic
    if final_amount > 30000:
        recommendations.append("High out-of-pocket expense. Consider insurance optimization.")
    else:
        recommendations.append("Repair cost is manageable.")

    return recommendations




if __name__ == '__main__':
    app.run(debug=True)

