def generate_recommendation(repair_days, depreciation, final_amount):
    recommendations = []

    # Repair time logic
    if repair_days > 7:
        recommendations.append("Vehicle may require extended workshop time. Plan alternate transport.")
    else:
        recommendations.append("Repair duration is within normal range.")

    # Depreciation logic
    if "High" in depreciation or "-" in depreciation:
        recommendations.append("Significant resale value impact expected.")
    else:
        recommendations.append("Minimal impact on resale value.")

    # Cost logic
    if final_amount > 30000:
        recommendations.append("High out-of-pocket expense. Consider insurance optimization.")
    else:
        recommendations.append("Repair cost is manageable.")

    return recommendations

